import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank

B = Bank('127.', 1085, own='cte_8.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---------------- 127.51 Veterinary Science ----------------
H('51.d.1.A',2,"A student in veterinary science wants to map out a future job. Which choice lists real paths to explore?","Veterinary technician, veterinarian, or clinic owner",["Animal clipper only","Pet toy designer only","Kennel painter only"],"Vet science leads to many careers, including technician, veterinarian and practice owner. Learning the education needed for each helps with planning.")
H('51.d.1.A',3,"Which step best helps a vet science student compare career and education options?","Researching the schooling, licensing, and pay for each job",["Choosing the job with the shortest name","Picking whatever a friend picked","Waiting until after graduation to look"],"Comparing training, licensing and pay for several jobs gives facts for a good decision.")
H('51.d.1.B',2,"In a vet clinic, which habit shows professionalism?","Arriving on time and ready to work",["Texting during appointments","Skipping tasks nobody checks","Leaving messes for the next shift"],"Reliable attendance and focus are core work habits that build trust with clients and coworkers.")
H('51.d.1.B',3,"A clinic assistant is stuck on a scheduling conflict. What is the most professional response?","Think through options and ask a supervisor if needed",["Ignore the problem","Blame a coworker","Quit the task without telling anyone"],"Problem solving and asking for help when needed are signs of professionalism.")
H('51.d.1.C',2,"Why must a veterinary worker wear gloves when handling a sick animal?","To protect against germs and infection",["To look more official","To keep the animal warm","To make the animal sit still"],"Protective gear reduces the chance of spreading disease between animals and people.")
H('51.d.1.C',3,"Which is a safe practice in a veterinary workplace?","Reporting injuries and hazards right away",["Hiding minor bites","Skipping eye protection to save time","Lifting heavy animals alone without help"],"Prompt reporting lets the clinic treat injuries and fix hazards before others are hurt.")
H('51.d.1.D',3,"A veterinary employee reads about client privacy. This is an example of an employee:","Responsibility to keep client and patient records private",["Right to share records online","Duty to post pet photos publicly","Option to gossip about owners"],"Confidentiality is an ethical duty in veterinary work. Records are shared only with permission or as the law requires.")
H('51.d.1.D',4,"Which action shows ethical conduct for a vet assistant who makes a mistake with a medication label?","Telling the supervisor right away so it can be corrected",["Quietly relabeling and saying nothing","Blaming the owner","Hoping nobody notices"],"Honesty about errors protects the patient and keeps the clinic accountable.")
H('51.d.1.E',2,"Which action shows good citizenship in the animal health field?","Volunteering at a local animal shelter vaccination day",["Ignoring community rules","Dumping medical waste in trash cans","Avoiding all community events"],"Citizenship includes giving time to community animal care projects and following the rules that protect public health.")
H('51.d.1.E',3,"A good citizen who works with animals would:","Follow local licensing and rabies laws",["Skip pet licensing","Let pets roam to save time","Hide sick animals from officials"],"Laws about licensing and rabies protect both animals and people in the community.")
H('51.d.2.A',3,"A vet science student plans a project of caring for a flock of chickens and tracking their health for a semester. This is best called a:","Supervised agricultural experience",["Scholarship exam","Field trip report","Banquet program"],"An SAE is hands-on work with a plan, goals and an adult supervisor outside regular class time.")
H('51.d.2.A',2,"Who helps a student set up and review a veterinary science supervised experience?","A teacher or other adult supervisor",["Nobody; it needs no oversight","Only the student's classmates","A stranger online"],"Supervision means an adult guides and checks the plan and the work.")
H('51.d.2.B',2,"Why should a student record dates, hours, and costs of an animal care project?","To measure progress and show what was learned",["To make the project look bigger","So records can be thrown away","Because animals read them"],"Good records show growth, costs and skills, and support awards and applications.")
H('51.d.2.B',3,"Which entry belongs in a vet-science project record book?","A log of vaccines given to a pet, with dates",["A joke list","A favorite recipe","A map of a mall"],"Accurate, dated animal care entries make records useful for evaluation.")
H('51.d.3.A',2,"Which activity builds leadership in a veterinary science class?","Leading a service project at an animal shelter",["Sitting out all club events","Letting others do all the work","Skipping meetings"],"Taking responsibility for a group service project builds leadership skills.")
H('51.d.3.B',2,"A chapter's local program of activities for a vet science club could include:","Planning a pet-care awareness night",["Cancelling all events","Keeping plans secret","Only voting without meeting"],"A local program of activities lists the events, service and goals members plan for the year.")
H('51.d.3.B',3,"Members who help carry out the club's yearly plan are:","Taking part in a local program of activities",["Breaking chapter rules","Skipping club business","Doing unpaid tutoring only"],"Reviewing and joining the planned events is how members support the program.")
H('51.d.3.C',2,"A resume for a vet-science student could list:","Volunteer hours at a shelter and chapter service",["Only favorite foods","Nothing, since experience does not count","Test scores from other subjects only"],"Documenting work, volunteering and service shows relevant experience.")
H('51.d.3.C',3,"Why update a record of animal-related experience each year?","To keep an accurate, current history for jobs and applications",["To avoid learning new skills","Because old items vanish on their own","To make it longer than needed"],"Current documentation supports resumes, scholarships and degree programs.")

H('51.d.4.A',2,"Why do vet workers learn proper animal restraint?","To protect both the animal and the handler during care",["To make animals fear the clinic","To speed up payment","To avoid wearing gloves"],"Safe restraint lowers the risk of bites, scratches and injuries.")
H('51.d.4.A',3,"Which is a safe way to lift a large dog?","Bend the knees and get help to lift it",["Lift fast with a bent back","Hold only by the front legs","Lift while the dog is struggling, alone"],"Using the legs and getting help protects the worker's back and the dog's joints.")
H('51.d.4.B',2,"A disease that can spread from animals to humans is called:","Zoonotic",["Genetic","Nutritional","Mechanical"],"Zoonotic diseases such as rabies move between animals and people.")
H('51.d.4.B',3,"Which step helps prevent spreading a zoonotic disease at work?","Washing hands after every animal contact",["Eating lunch in the exam room","Sharing food with patients","Touching your face during procedures"],"Hand washing and clean habits stop pathogens from moving between animals and people.")
H('51.d.4.C',2,"Which of these is a sanitation method for exam tables?","Disinfecting the surface between patients",["Wiping once at the end of the week","Covering with a towel and leaving it","Spraying only air freshener"],"Cleaning and disinfecting after each patient prevents the spread of germs.")
H('51.d.4.C',3,"Why are kennels cleaned and disinfected on a schedule?","To reduce pathogens and keep animals healthy",["To make the room smell stronger","To keep animals awake","To save on supplies"],"Regular sanitation controls disease in places where many animals live.")
H('51.d.4.D',2,"What does an SDS tell a clinic worker?","How to safely handle and store a chemical",["How much a chemical costs","Who the pet owner is","What the animal weighs"],"A safety data sheet lists hazards, first aid and handling for a chemical product.")
H('51.d.4.D',3,"A worker spills a cleaning chemical. Where should they check for the correct clean-up steps?","The safety data sheet for the product",["A magazine","The patient chart","The price list"],"The SDS gives spill response, protective gear and first aid information.")
H('51.d.4.E',2,"Before using clinical equipment such as clippers, a worker should:","Learn the correct and safe way to operate it",["Try it without instruction","Use it only on people","Borrow it without asking"],"Training prevents injuries to the animal and the user.")
H('51.d.4.E',3,"Which choice shows safe equipment use?","Unplugging clippers before cleaning the blades",["Cleaning blades while plugged in","Leaving blades running unattended","Passing a running tool to a coworker"],"Power should be off before cleaning to prevent cuts or shocks.")
H('51.d.4.F',2,"Where should used needles be placed?","In a labeled sharps container",["In the regular trash","On the counter","In a coat pocket"],"A puncture-proof sharps container prevents needle sticks.")
H('51.d.4.F',3,"Which waste belongs in a biohazard container?","Items soiled with blood or body fluids",["Clean paper towels","Empty food cans","Unused office paper"],"Contaminated materials must be separated to prevent disease spread.")

H('51.d.5.A',3,"Why do vet students study the history of animal medicine?","To see how past events and trends shaped current practice",["To avoid learning anatomy","To skip current laws","To memorize only dates"],"Understanding history helps explain why today's methods and rules exist.")
H('51.d.5.A',4,"Which topic is a current issue studied in veterinary medicine?","Antibiotic resistance in animal treatment",["Pricing of school lunches","Rules for car racing","Fashion trends"],"Antibiotic resistance affects both animal and human health and shapes practice.")
H('51.d.5.B',3,"Veterinary medical ethics includes:","Making decisions about animal welfare and euthanasia with care",["Ignoring animal pain","Keeping fees secret from owners","Sharing a client's records for fun"],"Ethics guides how vets weigh animal welfare, owner wishes and professional duty.")
H('51.d.5.B',4,"A vet is asked to perform a procedure that would harm the animal with no medical reason. The ethical response is to:","Decline and explain the animal's welfare concerns",["Do it for extra pay","Do it quickly and say nothing","Let an assistant do it instead"],"Professional ethics put animal welfare and medical need before convenience.")
H('51.d.5.C',3,"A clinic's written policies on records and drug storage reflect:","Local, state, and federal rules for veterinary medicine",["Only the owner's mood","Random preferences","Rules from other industries"],"Clinic policies follow laws and regulations for safe, legal practice.")
H('51.d.5.C',4,"Why do clinics have written protocols for common procedures?","To keep care consistent, safe, and legal",["To slow down staff","To avoid training","To hide mistakes"],"Standard procedures reduce errors and meet legal requirements.")

H('51.d.6.A',2,"The human-animal bond affects veterinary care because owners:","Often make care decisions based on how close they are to the pet",["Never care about their pets","Never visit a clinic","Follow only the cheapest advice"],"The bond influences how clients view treatment, cost and comfort.")
H('51.d.6.A',3,"A client is grieving a pet's death. Which response shows understanding of the bond?","Speaking with kindness and giving them time",["Rushing them out the door","Joking about the loss","Talking only about the bill"],"Compassion supports the client and builds trust.")
H('51.d.6.B',2,"Which is good client communication?","Explaining a treatment plan in clear, simple words",["Using only medical jargon","Avoiding eye contact","Interrupting the owner"],"Clear language helps owners understand and follow care instructions.")
H('51.d.6.B',3,"An owner seems confused about a medicine schedule. What should the assistant do?","Repeat it in plain language and provide it in writing",["Say it faster","Assume they understood","Tell them to ask the internet"],"Checking understanding and giving written steps improves compliance.")
H('51.d.6.C',2,"Which is a way a clinic markets its services?","Sharing pet health tips and reminders with clients",["Hiding its location","Avoiding all communication","Closing during business hours"],"Marketing helps clients learn about services and stay engaged.")
H('51.d.6.C',3,"How does good marketing help a veterinary practice?","It brings in clients and supports the practice's success",["It replaces medical care","It removes the need for staff","It stops disease directly"],"Marketing attracts and keeps clients, which supports the business and animal care.")
H('51.d.6.D',2,"Which technology helps a clinic manage appointments?","Computer scheduling software",["A chalkboard in the parking lot","Paper notes thrown away daily","A single sticky note"],"Software handles scheduling, records and reminders efficiently.")
H('51.d.6.D',3,"Electronic medical records help a clinic by:","Storing patient histories so they are quick to find",["Making notes unreadable","Preventing owners from calling","Removing the need for accuracy"],"Electronic records are organized, searchable and easily shared with permission.")

H('51.d.7.A',3,"The prefix 'hyper-' in veterinary terms means:","Above or excessive",["Below or lacking","Without","Around"],"Hyper- means excessive, as in hyperthermia, a high body temperature.")
H('51.d.7.A',4,"In 'gastritis', the suffix '-itis' means:","Inflammation",["Removal","Study of","Cutting"],"-itis means inflammation, so gastritis is inflammation of the stomach.")
H('51.d.7.B',2,"Why is correct spelling of veterinary terms important in medical records?","Errors can cause confusion or mistakes in treatment",["It makes the chart longer","It does not matter","It only matters for owners"],"Precise terms prevent misreads of diagnoses and medications.")
H('51.d.7.B',3,"Which is the correct spelling of the animal term for a female dog giving birth?","Whelping",["Welping","Wheeling","Whelpping"],"Whelping is the term for a dog giving birth.")
H('51.d.7.C',2,"The term 'dorsal' refers to the:","Back or top side",["Belly side","Front end","Tail only"],"Dorsal means toward the back (spine side).")
H('51.d.7.C',3,"Which direction term means toward the head?","Cranial",["Caudal","Ventral","Medial"],"Cranial means toward the head; caudal means toward the tail.")

H('51.d.8.A',2,"Animal breeds are identified by:","Physical traits such as size, coat, and ear shape",["Name tags only","Owner's address","Time of day"],"Breed characteristics are visible features inherited within a group.")
H('51.d.8.A',3,"A Holstein is a breed of:","Dairy cattle",["Sheep","Swine","Horse"],"Holsteins are known for high milk production.")
H('51.d.8.B',3,"Which is an example of abnormal behavior in a normally social dog?","Sudden hiding and refusing food",["Wagging its tail","Playing with toys","Sleeping after a walk"],"A sudden change in behavior can signal pain or illness.")
H('51.d.8.B',4,"Why compare behavior among species?","Normal behavior differs for dogs, cats, horses, and livestock",["All species behave the same","Only dogs have behaviors","Behavior has no medical value"],"Knowing species norms helps spot signs of stress or illness.")
H('51.d.8.C',2,"Why do handlers approach horses from the side where the horse can see them?","To avoid startling the animal",["To speed up the exam","To scare it","Because horses cannot hear"],"Calm, visible approaches reduce the chance of kicks and injuries.")
H('51.d.8.C',3,"Which is a basic restraint tool for a cat?","A towel wrap",["A rope tied to a fence","A spiked collar","A heavy chain"],"A towel wrap safely limits movement and calms many cats.")

H('51.d.9.A',2,"Which body system includes bones that support the animal?","Skeletal",["Respiratory","Digestive","Urinary"],"The skeletal system supports the body and protects organs.")
H('51.d.9.A',3,"The main job of the respiratory system is to:","Move oxygen in and carbon dioxide out",["Digest food","Filter blood only","Produce hormones only"],"Lungs exchange gases to supply oxygen to the body.")
H('51.d.9.B',3,"Which statement shows body systems work together?","The circulatory system carries oxygen taken in by the respiratory system",["Each system works alone","The digestive system never needs blood","The nervous system stops all others"],"Systems are interdependent; blood moves oxygen from the lungs to tissues.")
H('51.d.9.B',4,"If the kidneys fail to remove wastes, what other system is affected?","Circulatory, because wastes build up in the blood",["None","Only the skeletal system","Only the hair coat"],"Kidney failure allows toxins to accumulate in the blood and affect many organs.")

H('51.d.10.A',2,"Which feed is a common source of protein for dogs?","Meat-based dog food",["Plain water","Sand","Salt only"],"Meat and legumes supply protein, an essential nutrient.")
H('51.d.10.A',3,"Hay and pasture are classes of feed called:","Roughages",["Concentrates","Supplements only","Minerals only"],"Roughages are high-fiber feeds for livestock like horses and cattle.")
H('51.d.10.B',3,"A feed additive such as a vitamin supplement is used to:","Fill nutrient gaps in the diet",["Replace all feed","Reduce water needs","Make food less safe"],"Additives provide nutrients or other benefits the basic ration lacks.")
H('51.d.10.B',4,"Why must feed additives be used carefully?","Too much or the wrong type can harm the animal",["They never matter","They only change color","They are always required by law"],"Dosage and species suitability matter for safety.")
H('51.d.10.C',3,"A senior dog with kidney trouble often needs:","A diet formulated for its condition",["The same food as a puppy","No food at all","Only table scraps"],"Life stage and health conditions change dietary needs.")
H('51.d.10.C',4,"Moldy feed is a feed-quality issue because it can:","Produce toxins that make animals sick",["Add extra vitamins","Improve digestion","Increase water content safely"],"Mold can release mycotoxins that harm health.")
H('51.d.10.D',3,"A prescription diet differs from a regular diet in that it:","Is formulated to treat a specific medical condition",["Costs less always","Has no nutrients","Is only for humans"],"Therapeutic diets are used to help manage disease under veterinary direction.")
H('51.d.10.D',4,"To compare two foods, a vet reads the:","Guaranteed analysis and ingredient list",["Brand logo","Bag color","Barcode only"],"Labels show nutrient percentages and ingredients for comparison.")

H('51.d.11.A',2,"A healthy dog usually has:","Bright eyes, a clean coat, and a good appetite",["Dull eyes and a matted coat","Constant coughing","Refusal to drink"],"Alert, bright animals with normal eating habits are generally healthy.")
H('51.d.11.A',3,"Which sign suggests an animal may be unhealthy?","Lethargy with a loss of appetite",["Playful energy","Normal stools","Clear eyes"],"Lethargy and appetite change are common signs of illness.")
H('51.d.11.B',3,"Vital signs commonly checked in an exam include:","Temperature, pulse, and respiration",["Hair length","Collar size","Eye color"],"TPR are core vital signs for assessing health.")
H('51.d.11.B',4,"Normal vital sign ranges differ because:","Each species and size has its own healthy range",["All animals share one range","They are random","Only age matters, never species"],"Heart rate and temperature vary by species and size.")
H('51.d.11.C',3,"To take a dog's pulse, a technician commonly:","Feels the femoral artery in the inner thigh",["Checks the ear tip","Holds the tail","Presses the nose"],"The femoral pulse is easily felt in dogs and cats.")
H('51.d.11.C',4,"A rectal temperature is taken using:","A lubricated thermometer",["A dry glass rod forced in","A tape measure","A stethoscope only"],"Lubrication and gentle technique make the measurement safe.")
H('51.d.11.D',3,"Which factor can raise an animal's heart rate temporarily?","Stress or fear",["Quiet rest","A calm voice","A cool room"],"Fear and excitement increase heart and respiration rates.")
H('51.d.11.D',4,"Why consider age when interpreting vital signs?","Young animals have higher heart rates than adults",["They never change","Older animals always have the highest","Age does not affect physiology"],"Normal values shift across life stages.")
H('51.d.11.E',2,"A physical exam usually begins with:","Observing the animal's general appearance",["Surgery","Giving injections","Removing hair"],"Observation reveals posture, behavior and body condition before hands-on steps.")
H('51.d.11.E',3,"During a physical exam, the vet listens to the heart using a:","Stethoscope",["Scalpel","Syringe","Microscope"],"Auscultation uses a stethoscope to hear heart and lung sounds.")
H('51.d.11.F',3,"The regional approach to assessing health means examining:","Each area of the body in an organized order",["Only the eyes","Only the paws","The animal's paperwork only"],"Systematically checking head, neck, trunk and limbs ensures nothing is missed.")
H('51.d.11.F',4,"A benefit of an anatomical regional exam is that it:","Reduces the chance of overlooking an abnormality",["Replaces lab tests","Makes the exam shorter every time","Needs no training"],"A consistent order helps find problems.")
H('51.d.11.G',3,"A cat weighs 8 pounds today and weighed 10 pounds last month. How much did it lose?","2 pounds",["1 pound","3 pounds","18 pounds"],"10 minus 8 equals 2 pounds, a 20 percent loss, which is significant.")
H('51.d.11.G',4,"A dog weighs 44 pounds. About how many kilograms is that (1 kg = 2.2 lb)?","20 kg",["10 kg","44 kg","97 kg"],"44 divided by 2.2 equals 20 kilograms.")
H('51.d.11.H',3,"A growth chart shows a puppy's weight rising steadily over weeks. This pattern suggests:","Normal growth",["Weight loss","No change","Illness always"],"A steady upward line matches healthy growth.")
H('51.d.11.H',4,"On a weight graph, a sudden drop in an adult dog's line may signal:","A health problem that needs attention",["Perfect health","Better nutrition always","A broken chart"],"Rapid unexplained weight loss warrants investigation.")

H('51.d.12.A',3,"Vaccines help an animal by:","Training the immune system to recognize a pathogen",["Killing all bacteria in the body","Replacing food","Changing the animal's DNA"],"Vaccines prime immunity without causing the full disease.")
H('51.d.12.A',4,"A disease spread by direct contact between animals is:","Transmitted by touching or close contact",["Always airborne only","Never contagious","Spread only by plants"],"Direct transmission occurs through contact, bites or fluids.")
H('51.d.12.B',3,"A virus differs from a bacterium because a virus:","Needs a host cell to reproduce",["Is a large animal","Makes its own food","Is visible without tools"],"Viruses replicate only inside host cells.")
H('51.d.12.B',4,"Canine parvo, which attacks the gut of puppies, is caused by which kind of pathogen?","A viral agent",["A bacterium","A fungus","A tapeworm"],"Canine parvo is a viral disease that attacks the gut.")
H('51.d.12.C',3,"A respiratory infection can show up as:","Coughing and nasal discharge",["Limping only","Hair color change","Gaining weight"],"Respiratory disease affects the airways and lungs.")
H('51.d.12.C',4,"Diarrhea and vomiting point most directly to disease in the:","Digestive system",["Skeletal system","Reproductive system","Integumentary system"],"These signs indicate GI tract disturbance.")
H('51.d.12.D',3,"Fleas and ticks are examples of:","External parasites",["Internal parasites","Bacteria","Viruses"],"They live on the outside of the host.")
H('51.d.12.D',4,"Roundworms and hookworms are classified as:","Internal parasites",["External parasites","Fungi","Protozoa only"],"They live inside the host's intestines.")
H('51.d.12.E',3,"A parasite life cycle describes:","The stages a parasite goes through from egg to adult",["Only the adult stage","The drug used","The host's diet"],"Knowing the cycle shows where it can be stopped.")
H('51.d.12.E',4,"Why do vets learn life cycles of parasites?","To time treatment and prevention at the right stage",["To decide on grooming","To pick leash types","To order food"],"Breaking the cycle controls infestations.")
H('51.d.12.F',3,"Tapeworms in dogs can be transmitted when a dog:","Swallows an infected flea",["Plays fetch","Takes a bath","Eats dry kibble from a sealed bag"],"Dogs get certain tapeworms by eating fleas carrying larvae.")
H('51.d.12.F',4,"Heartworm is spread by:","Mosquitoes",["Direct touching of paws","Contaminated water bowls only","Dry air"],"Mosquitoes carry larvae from animal to animal.")
H('51.d.12.G',3,"A fecal flotation test is used to find:","Parasite eggs in stool",["Blood sugar","Bone fractures","Vitamin levels"],"The test floats eggs so they can be seen under a microscope.")
H('51.d.12.G',4,"Which test can detect heartworm?","A blood test for antigens",["A fecal float","A skin scraping for lice","An X-ray of the paw"],"Heartworm antigen tests are done on blood.")
H('51.d.12.H',3,"A common treatment for intestinal worms is:","A deworming medication",["A vitamin","A haircut","A bath only"],"Dewormers are given according to the parasite found.")
H('51.d.12.H',4,"Prevention products given monthly protect pets from:","Heartworm and some other parasites",["Hunger","Dental decay","Nail growth"],"Monthly preventives interrupt parasite life cycles.")

H('51.d.13.A',3,"A fecal sample should be:","Fresh and labeled with the patient's information",["Old and unlabeled","Frozen for a year","Mixed with others"],"Proper handling preserves the sample and prevents mix-ups.")
H('51.d.13.A',4,"Why wear gloves when collecting a urine sample?","To avoid exposure to pathogens",["To keep hands warm","To make the sample bigger","Because the dog requires it"],"Body fluids can carry disease.")
H('51.d.13.B',3,"A urinalysis can help detect:","Kidney problems and infection",["Broken bones","Poor eyesight","Dental tartar"],"Urine tests show how kidneys and the urinary tract are working.")
H('51.d.13.B',4,"Blood tests are commonly run to check:","Organ function and infection",["Only nail length","Hair color","Collar fit"],"A CBC and chemistry panel give information on organs and cells.")
H('51.d.13.C',3,"A high white blood cell count often suggests:","Infection or inflammation",["Perfect health","Dehydration only","Poor hair coat"],"White cells increase to fight infection.")
H('51.d.13.C',4,"When comparing results to normal ranges, a value far outside the range should be:","Reported to the veterinarian",["Ignored","Erased","Rounded to match"],"Abnormal results need professional interpretation.")

H('51.d.14.A',3,"After use, surgical instruments should be:","Cleaned and sterilized before storing",["Left dirty overnight","Stored wet","Shared without cleaning"],"Cleaning and sterilizing prevents infection.")
H('51.d.14.A',4,"Equipment maintenance logs are kept to:","Track cleaning, calibration, and repairs",["Hide problems","Replace training","Reduce records"],"Maintenance logs show devices are safe and working.")
H('51.d.14.B',3,"A veterinary medical record must be:","Accurate, complete, and kept confidential",["Short and vague","Shared on social media","Left out in the lobby"],"Records document care and protect client privacy.")
H('51.d.14.B',4,"If an error is made on a paper chart, the correct fix is to:","Draw a single line through it, initial and date it",["Use white-out","Rip out the page","Erase fully"],"Original entries must remain readable for legal accuracy.")
H('51.d.14.C',2,"Trimming nails is an example of:","Routine animal care",["Emergency surgery","Imaging","Necropsy"],"Nail trims, ear cleaning and bathing are routine tasks.")
H('51.d.14.C',3,"Before giving an oral medication, a technician should:","Verify the dose and the patient's identity",["Guess the dose","Mix several drugs","Skip the chart"],"Double-checking prevents medication errors.")
H('51.d.14.D',3,"Therapeutic care for a patient recovering from surgery includes:","Pain management and wound care",["Ignoring the incision","Free-range running","Skipping medications"],"Supporting recovery reduces pain and complications.")
H('51.d.14.D',4,"Giving fluids to a dehydrated animal is an example of:","Supportive therapy",["Diagnostic imaging","Grooming","Behavior training"],"Fluids restore hydration and support the body.")
H('51.d.14.E',3,"If an animal stops breathing, the first priority is to:","Alert the vet and start emergency protocol",["Wait and see","Give food","Take a photo"],"Quick action and clear protocols save lives.")
H('51.d.14.E',4,"First aid for a bleeding wound includes:","Applying direct pressure with clean gauze",["Pouring on peroxide repeatedly","Removing all pressure","Covering with tape only"],"Pressure helps control bleeding until a vet can treat the wound.")
H('51.d.14.F',3,"Geriatric patients often need:","Extra monitoring for age-related conditions",["No exams","Only puppy food","Strenuous exercise"],"Older animals commonly have joint, kidney and heart issues.")
H('51.d.14.F',4,"Exotic pet care differs from dog care because exotics:","Have unique housing, diet, and handling needs",["Need identical care","Never get sick","Cannot be treated"],"Species-specific knowledge is required for birds, reptiles and small mammals.")

H('51.d.15.A',3,"Pre-surgical care often includes:","Fasting the animal as directed and running pre-op blood work",["Feeding a large meal","Skipping exams","No monitoring"],"Fasting reduces vomiting under anesthesia; labs check readiness.")
H('51.d.15.A',4,"After surgery, owners are typically told to:","Limit activity and watch the incision",["Encourage jumping","Remove the bandage right away","Skip medication"],"Rest and incision monitoring support healing.")
H('51.d.15.B',3,"A scalpel is used to:","Make incisions",["Measure temperature","Hold a patient","Clean teeth"],"Scalpels cut tissue in surgery.")
H('51.d.15.B',4,"Hemostats are used to:","Clamp blood vessels",["Hold the animal's head","Measure heart rate","Cut hair"],"Hemostats control bleeding by clamping vessels.")
H('51.d.15.C',3,"An autoclave sterilizes surgical packs using:","Steam under pressure",["Cold water","Dry air only","Soap alone"],"High-pressure steam kills microbes.")
H('51.d.15.C',4,"A sterile surgical pack should be opened:","Without touching the sterile contents",["On the floor","After sneezing on it","With dirty hands"],"Sterile technique prevents contamination.")
H('51.d.15.D',3,"Spaying is the surgical removal of a female animal's:","Reproductive organs",["Teeth","Tail","Ears"],"An ovariohysterectomy prevents pregnancy.")
H('51.d.15.D',4,"Neutering a male animal is called:","Castration",["Declawing","Spaying","Biopsy"],"Castration removes the testicles.")

H('51.d.16.A',3,"An X-ray machine produces images using:","Radiation passing through the body",["Sound waves only","Magnets only","Visible light only"],"X-rays differ in absorption by bone and tissue.")
H('51.d.16.A',4,"Ultrasound creates images with:","High-frequency sound waves",["X-rays","Heat","Radio stations"],"Echoes of sound waves form moving images of soft tissue.")
H('51.d.16.B',3,"Staff taking X-rays should wear:","Lead aprons and use dosimeter badges",["Open shirts","Jewelry","Sandals"],"Lead blocks scatter radiation and badges track exposure.")
H('51.d.16.B',4,"The best way to limit radiation exposure is to:","Stay back and keep hands out of the beam",["Hold the animal by hand","Stand in the beam","Skip the apron"],"Distance and shielding reduce exposure.")
H('51.d.16.C',3,"Positioning for an X-ray is important because:","It affects the quality and usefulness of the image",["It makes no difference","It prevents the need for restraint","It speeds up billing"],"Correct positioning shows the body part clearly.")
H('51.d.16.C',4,"Sedation may be used for imaging to:","Keep the animal still and reduce stress",["Make it bark more","Replace the image","Heal the problem"],"Stillness gives better images and protects staff.")
H('51.d.16.D',3,"Which image would best show a fractured bone?","An X-ray",["A blood test","A urine test","A fecal float"],"Bones appear clearly on radiographs.")
H('51.d.16.D',4,"Which tool is best to view the heart's moving chambers?","Ultrasound",["Plain film X-ray alone","A scale","A thermometer"],"Ultrasound shows real-time motion of soft tissues.")

H('51.d.17.A',3,"Antibiotics are used to treat:","Bacterial infections",["Viral infections","Broken bones","Hunger"],"Antibiotics act on bacteria, not viruses.")
H('51.d.17.A',4,"A controlled substance schedule indicates:","How tightly a drug is regulated for abuse potential",["The drug's color","The flavor","Its brand name"],"Schedules rank legal restrictions on drugs.")
H('51.d.17.B',3,"Controlled drugs in a clinic must be:","Locked, logged, and accounted for",["Left on the counter","Shared freely","Unrecorded"],"Law requires secure storage and records.")
H('51.d.17.B',4,"Expired medications should be:","Removed and disposed of properly",["Given to patients","Kept mixed with fresh stock","Sold at a discount"],"Expired drugs may be ineffective or unsafe.")
H('51.d.17.C',3,"A 10 kg dog needs 5 mg of a drug per kg. What is the dose?","50 mg",["5 mg","15 mg","2 mg"],"10 times 5 equals 50 mg.")
H('51.d.17.C',4,"A drug is 100 mg per mL. The dose is 250 mg. How many mL are needed?","2.5 mL",["0.4 mL","25 mL","1.5 mL"],"250 divided by 100 equals 2.5 mL.")
H('51.d.17.D',3,"A prescription label must include:","Patient name, drug, dose, and directions",["Only the clinic's logo","A cartoon","The owner's favorite food"],"Clear identification and instructions ensure safe use.")
H('51.d.17.D',4,"Why list the expiration date on a label?","So the owner knows when the medication is no longer safe to use",["It is decoration","To hide the drug name","To increase price"],"Drugs lose potency or become unsafe after expiring.")
H('51.d.17.E',3,"A syringe is used to:","Measure and give liquid medication or injections",["Cut hair","Clean teeth","Weigh animals"],"Syringes deliver measured doses.")
H('51.d.17.E',4,"Choosing a needle gauge depends on:","The medication and the animal's size",["The color of the hub","The clinic's phone number","The weather"],"Larger gauges are thinner needles; selection matches the use.")
H('51.d.17.F',4,"An emerging trend in veterinary pharmacology is:","Targeted therapies and new drug delivery methods",["Banning all medication","Using only herbs for all disease","Eliminating research"],"New treatments and delivery options such as long-acting injectables continue to develop.")
H('51.d.17.F',5,"Why research new veterinary drugs and therapies?","To improve treatment results while evaluating safety",["To make care slower","To reduce understanding","To avoid regulation"],"Ongoing study aims for effective, safe care.")

# ---------------- 127.52 Animal Science ----------------
H('52.d.1.A',2,"A student interested in animal science could consider a career as:","Dairy nutritionist, livestock breeder, or farm manager",["Only a lawyer","Only a pilot","Only a chef"],"Animal science leads to many jobs in production, nutrition and management.")
H('52.d.1.A',3,"Starting an animal-product business is an example of:","Entrepreneurship in agriculture",["A school rule","A required class","A hobby only"],"Entrepreneurs build and run their own animal-related ventures.")
H('52.d.1.B',2,"Which shows professionalism on a livestock farm crew?","Following directions and finishing assigned chores",["Arriving late daily","Leaving gates open","Ignoring supervisors"],"Reliability and teamwork are expected on the job.")
H('52.d.1.B',3,"A worker finds a feeder broken. A professional response is to:","Report it and help find a fix",["Pretend not to see","Break it more","Blame someone"],"Problem solving and communication keep operations running.")
H('52.d.1.C',2,"Why wear boots and gloves while working with livestock?","To prevent injuries and lessen exposure to disease",["To impress visitors","To stay warm at night","They are never needed"],"Protective gear reduces foot injuries and contact with pathogens.")
H('52.d.1.C',3,"A safe practice around large animals is to:","Stay aware of their position and avoid blind spots",["Walk behind a horse quickly","Stand between a cow and her calf","Wear loose, dangling clothes"],"Awareness of animal behavior prevents kicks and crushing injuries.")
H('52.d.1.D',3,"An employee in animal agriculture has the right to:","A safe workplace and fair treatment",["Break animal welfare laws","Skip training","Ignore safety rules"],"Workers have legal rights and ethical duties.")
H('52.d.1.D',4,"Following animal welfare laws is an example of:","Ethical and lawful conduct",["Optional courtesy","Wasting time","Ignoring regulation"],"Laws set minimum standards of humane treatment.")
H('52.d.1.E',2,"A good citizen in agriculture might:","Help neighbors with animal care during an emergency",["Pollute water sources","Ignore property lines","Avoid community rules"],"Citizenship includes responsibility to neighbors and the environment.")
H('52.d.1.E',3,"Which is a responsible manure practice?","Applying it in amounts that protect nearby streams",["Dumping it in a river","Leaving piles in the road","Burning in a school yard"],"Careful handling protects water and community health.")
H('52.d.2.A',2,"In a lab, observing a sick calf and asking 'why' is how a scientist:","Defines a problem to study",["Ends an experiment","Writes a recipe","Prints a label"],"Science starts with observations and questions.")
H('52.d.2.A',3,"A good testable question about feed is:","Does protein level affect weight gain in lambs?",["Is feed good?","Do animals like grass?","Why is the sky blue?"],"A testable question identifies variables that can be measured.")
H('52.d.2.B',3,"A comparative investigation of two feeds should:","Change only the feed and keep everything else the same",["Change everything at once","Use no animals","Skip measurements"],"Controlled variables make the comparison fair.")
H('52.d.2.B',4,"Repeating a trial several times helps to:","Increase confidence in the results",["Hide errors","Ensure the result is wrong","Remove the need for data"],"More trials reduce the effect of chance.")
H('52.d.2.C',2,"Before a lab dissection, students should:","Review safety rules and wear protective gear",["Skip safety talk","Eat in the lab","Share tools with no cleaning"],"Safety practices prevent injuries and contamination.")
H('52.d.2.C',3,"Preserved specimens should be handled with:","Gloves, goggles, and proper ventilation",["Bare hands","Open flame","Food nearby"],"Preservatives can irritate skin and eyes.")
H('52.d.2.D',2,"A graduated cylinder is used to measure:","Volume of a liquid",["Temperature","Mass","Length"],"Its marks show liquid volume in milliliters.")
H('52.d.2.D',3,"Which tool lets students see cell structure in a tissue sample?","A microscope",["A meter stick","A scale","A ruler"],"Microscopes magnify tiny structures.")
H('52.d.2.E',2,"The SI unit for mass is the:","Kilogram",["Pound","Foot","Gallon"],"Mass in SI is measured in kilograms or grams.")
H('52.d.2.E',3,"Which is qualitative data about a calf?","The coat is shiny and smooth",["The calf weighs 90 kg","The calf is 3 weeks old","Its temperature is 38.6 C"],"Qualitative data describes qualities without numbers.")
H('52.d.2.F',3,"A spreadsheet is useful for data because it can:","Organize numbers and do calculations quickly",["Replace all experiments","Give results with no input","Prevent errors always"],"Software helps sort, sum and graph data.")
H('52.d.2.F',4,"A bar graph of average daily gain for three feeds helps to:","Compare the groups visually",["Hide differences","Remove variables","Skip analysis"],"Graphs make comparisons clear.")
H('52.d.2.G',3,"A scale model of a cow's digestive tract is used to:","Represent a system that is hard to see directly",["Replace the real animal","Change the animal","Prove nothing"],"Models help explain processes and structures.")
H('52.d.2.G',4,"A limitation of a model is that it:","Simplifies reality and may leave out details",["Is always exact","Needs no testing","Works for every question"],"Models are useful but never perfect copies.")
H('52.d.2.H',3,"A scientific theory is:","A well-supported explanation based on a lot of evidence",["A random guess","A hunch","An opinion"],"Theories are broad, tested explanations of natural events.")
H('52.d.2.H',4,"A scientific law usually:","Describes a pattern observed in nature",["Explains why it happens in full detail always","Is a guess","Can never be tested"],"Laws describe what happens; theories explain why.")
H('52.d.3.A',3,"An advantage of a computer model of herd growth is that it:","Lets researchers test changes without using real animals",["Is always perfect","Needs no data","Replaces farms"],"Models allow quick, low-cost testing of ideas.")
H('52.d.3.A',4,"A limit of a small-scale model is:","It may not capture real-world scale or complexity",["It is always accurate","It cannot be changed","It needs no data"],"Scale and simplification introduce limits.")
H('52.d.3.B',3,"When analyzing weight-gain data, a researcher looks for:","Patterns, averages, and outliers",["Only the biggest number","Only the smallest number","Nothing"],"Statistical features reveal what the data show.")
H('52.d.3.B',4,"An unusual data point far from the others is a(n):","Outlier",["Average","Constant","Variable"],"Outliers may signal error or a real difference.")
H('52.d.3.C',3,"A pen of 5 pigs gained 50 kg total. What is the mean gain per pig?","10 kg",["5 kg","250 kg","55 kg"],"50 divided by 5 equals 10 kg.")
H('52.d.3.C',4,"A steer gained 3.5 pounds per day for 20 days. About how much did it gain?","70 pounds",["23.5 pounds","7 pounds","17 pounds"],"3.5 times 20 equals 70 pounds.")
H('52.d.3.D',3,"Evaluating an experimental design includes checking whether it:","Controls variables and has enough trials",["Uses no data","Has no plan","Reaches a conclusion first"],"Good design leads to trustworthy results.")
H('52.d.3.D',4,"An engineering design for a feeder is evaluated by:","Testing whether it meets its goals within limits like cost",["Its color","Guessing","Ignoring cost"],"Designs are judged against criteria and constraints.")

H('52.d.4.A',3,"Scientists support an explanation with:","Data and models",["Opinions only","Rumors","Wishes"],"Evidence strengthens claims.")
H('52.d.4.A',4,"A solution to a feed-waste problem is stronger if it:","Is supported by test results",["Is popular only","Has no data","Uses guesses"],"Data backing improves credibility.")
H('52.d.4.B',2,"Sharing results with classmates and a teacher is a way to:","Communicate scientific explanations",["Hide findings","Avoid feedback","Skip learning"],"Communication lets others review and learn from findings.")
H('52.d.4.B',3,"A group presenting a livestock project should:","Explain its data clearly and give each member a role",["Read only the title","Leave out data","Work alone silently"],"Clear delivery and teamwork make good communication.")
H('52.d.4.C',3,"In a respectful scientific argument, students:","Support claims with evidence and listen to others",["Interrupt","Insult opponents","Ignore evidence"],"Respectful discussion focuses on evidence.")
H('52.d.4.C',4,"If new data contradicts your claim, a scientist should:","Reconsider the claim in light of the evidence",["Hide the data","Attack the data source","Ignore it"],"Good scientists revise ideas based on evidence.")
H('52.d.5.A',3,"Critiquing an explanation means:","Evaluating strengths and weaknesses using evidence",["Agreeing without reading","Rejecting automatically","Copying it"],"Critique is a careful, fair review.")
H('52.d.5.A',4,"A weak claim about a feed supplement would be one that:","Is not backed by data",["Uses repeated trials","Includes controls","Has clear measurements"],"Claims need supporting evidence.")
H('52.d.5.B',3,"Past research in animal breeding has changed science by:","Improving understanding of genetics and productivity",["Stopping all progress","Ending the need for data","Eliminating all animals"],"Earlier findings shaped current practice.")
H('52.d.5.B',4,"Research on animal disease control affects society by:","Protecting food safety and animal health",["Making food unsafe","Removing laws","Ending farming"],"Scientific work informs policy and practice.")
H('52.d.5.C',2,"To learn more about animal science careers, a student could visit:","A university extension office or museum",["A random stranger","A closed store","Nowhere"],"Professional organizations, museums and libraries offer reliable resources.")
H('52.d.5.C',3,"A good resource for animal science research is:","A professional journal or extension service",["A rumor","An unsigned post","A meme"],"Reliable sources are reviewed and credible.")

H('52.d.6.A',3,"A student's animal science SAE should include:","A plan, goals, and an adult supervisor",["No plan","No goals","No records"],"SAEs are planned, supervised and evaluated.")
H('52.d.6.A',4,"Raising and selling market lambs for profit is what type of SAE?","Entrepreneurship",["Placement","Exploratory observation","Research only"],"Owning and running a venture is entrepreneurship.")
H('52.d.6.B',2,"Why track feed costs in an animal science project?","To calculate profit or loss",["To waste time","To hide expenses","To lower animal weight"],"Cost records show how well the project performs financially.")
H('52.d.6.B',3,"A complete record book includes:","Income, expenses, and animal performance data",["Only photos","Only notes about weather","Nothing"],"Full records support analysis and awards.")
H('52.d.7.A',2,"Running for a chapter officer position is a way to:","Develop agricultural leadership",["Avoid responsibility","Skip teamwork","Escape meetings"],"Officers practice organizing, speaking and decision making.")
H('52.d.7.A',3,"Which opportunity lets a student lead in the animal science community?","Organizing a livestock judging practice for younger members",["Missing practice","Staying home","Ignoring the club"],"Leading others builds skills and community.")
H('52.d.7.B',2,"A program of activities is used by a chapter to:","Plan events and goals for the year",["Cancel meetings","Hide the budget","Close the club"],"It guides what the group accomplishes.")
H('52.d.7.B',3,"Helping the chapter set up a livestock show is an example of:","Participating in the local program of activities",["Breaking club rules","Avoiding service","Private business"],"Members support the planned events.")
H('52.d.7.C',3,"Documentation of an animal science experience may show:","Skills learned and hours worked",["Nothing useful","Only grades","Only friends' names"],"It supports applications and resumes.")
H('52.d.7.C',4,"Why update a list of animal experience each semester?","So it stays accurate for jobs and scholarships",["To lengthen it for no reason","To delete old skills","To prevent growth"],"Current documentation helps future opportunities.")

H('52.d.8.A',3,"Domestication of animals means:","Selecting animals over generations to live with and serve people",["Capturing any wild animal once","Releasing animals into the wild","Banning animals"],"Domestication is a long process of breeding for useful traits.")
H('52.d.8.A',4,"Dogs were among the first animals to be:","Domesticated",["Extinct","Cloned","Discovered on Mars"],"Dogs are descended from wolves and were domesticated long ago.")
H('52.d.8.B',4,"A change in the global food market, such as rising grain prices, can affect animal producers by:","Raising feed costs",["Eliminating demand","Removing all competition","Lowering all prices"],"Feed is a major cost, so grain price shifts matter.")
H('52.d.8.B',5,"A new export market for beef can:","Increase demand and prices for producers",["Eliminate farms","End trade","Reduce prices to zero"],"Greater demand typically raises prices.")
H('52.d.8.C',3,"A Hereford is a breed of:","Beef cattle",["Dairy goats","Swine","Poultry"],"Herefords are known for beef production.")
H('52.d.8.C',4,"When comparing breeds, producers look at:","Traits such as growth, temperament, and adaptability",["Names only","Colors only","Price of ink"],"Breed traits affect production and fit to environment.")

H('52.d.9.A',3,"Muscle cells and nerve cells differ because they:","Have structures suited to different functions",["Are identical","Have no nuclei","Do not exist"],"Specialized cells have specific forms.")
H('52.d.9.A',4,"A red blood cell is specialized to:","Carry oxygen",["Digest food","Send nerve signals","Produce milk"],"Hemoglobin carries oxygen.")
H('52.d.9.B',3,"Mitosis produces:","Two identical body cells",["Four sex cells","One cell","No cells"],"Mitosis is used for growth and repair.")
H('52.d.9.B',4,"Meiosis produces:","Gametes with half the chromosomes",["Identical body cells","More skin","Muscle fiber"],"Meiosis forms eggs and sperm with a half set.")
H('52.d.9.C',3,"Cell differentiation is the process by which:","Cells become specialized for different jobs",["Cells die","Cells become identical","Cells stop dividing"],"Differentiation forms tissues and organs.")
H('52.d.9.C',4,"Stem cells can:","Develop into several cell types",["Never change","Only become blood","Stop working"],"They are unspecialized and can differentiate.")
H('52.d.9.D',3,"The correct order from smallest to largest is:","Cell, tissue, organ, organ system",["Organ, cell, tissue, system","System, organ, tissue, cell","Tissue, system, cell, organ"],"Levels of organization build in complexity.")
H('52.d.9.D',4,"The stomach is an example of a(n):","Organ",["Cell","Tissue","Molecule"],"An organ is made of tissues working together.")

H('52.d.10.A',3,"Compared with dogs, cattle have:","Hooves and a multi-part stomach",["Claws and one stomach","Wings","Gills"],"Cattle are hoofed ruminants.")
H('52.d.10.A',4,"Horses differ from cattle in having:","A single-toed hoof and a simple stomach",["Four stomach compartments","Horns always","Gills"],"Horses are non-ruminant herbivores with a single digit hoof.")
H('52.d.10.B',3,"The function of the heart is to:","Pump blood through the body",["Digest food","Filter urine","Make bile"],"The heart circulates blood.")
H('52.d.10.B',4,"The kidneys are part of the:","Urinary system",["Digestive system","Skeletal system","Endocrine system only"],"They filter blood and produce urine.")
H('52.d.10.C',3,"The respiratory and circulatory systems work together to:","Deliver oxygen to tissues",["Digest feed","Make hair","Produce eggs"],"Lungs add oxygen; blood carries it.")
H('52.d.10.C',4,"If the circulatory system is weakened, which system is affected?","All systems that depend on blood supply",["None","Only the nails","Only the hair"],"Blood carries oxygen and nutrients everywhere.")

H('52.d.11.A',3,"Cattle are ruminants, meaning they have:","A four-compartment stomach",["One simple stomach","No stomach","Two lungs only"],"The rumen, reticulum, omasum and abomasum digest fibrous feed.")
H('52.d.11.A',4,"Pigs have what type of digestive system?","Monogastric",["Ruminant","Avian","Cecal only"],"Pigs have a single-compartment stomach.")
H('52.d.11.B',3,"Corn is a common source of:","Energy (carbohydrate)",["Vitamin K only","Water only","Calcium only"],"Grain supplies energy.")
H('52.d.11.B',4,"Soybean meal is used as a:","Protein supplement",["Mineral block","Water treatment","Bedding"],"It is a protein-rich feed ingredient.")
H('52.d.11.C',3,"A mineral supplement may provide:","Calcium and phosphorus",["Only sugar","Only water","Only fiber"],"Minerals support bones and metabolism.")
H('52.d.11.C',4,"Feed additives like ionophores are used to:","Improve feed efficiency in some livestock",["Cause disease","Remove nutrients","Add water"],"They change rumen fermentation for better gain.")
H('52.d.11.D',3,"Balancing a ration means:","Combining feeds to meet nutrient needs",["Using only one grain","Cutting all feed","Ignoring needs"],"Rations are formulated for the animal's requirements.")
H('52.d.11.D',4,"A lactating dairy cow needs a ration with:","Higher energy and protein than a dry cow",["Less energy","No protein","Only water"],"Milk production increases nutrient demands.")
H('52.d.11.E',3,"Feeding twice a day on a schedule helps because it:","Supports consistent intake and digestion",["Causes starvation","Removes variety","Confuses animals"],"Regular feeding supports health and growth.")
H('52.d.11.E',4,"Overfeeding grain to cattle can cause:","Digestive upset such as acidosis",["Faster hoof growth only","Lower weight","Better health always"],"Excess grain upsets rumen pH.")
H('52.d.11.F',3,"Moldy hay is a feed quality problem because it:","May contain toxins and reduce animal health",["Adds vitamins","Is more digestible","Costs more"],"Mold produces harmful compounds.")
H('52.d.11.F',4,"Dusty, weedy hay is of lower quality because it:","Offers less nutrition and may irritate animals",["Is always best","Has more protein","Cannot be eaten"],"Quality affects intake and health.")
H('52.d.11.G',3,"To compare feeds fairly, producers compare:","Nutrient content per unit of cost",["Bag color only","Brand names only","Smell only"],"Cost per nutrient shows value.")
H('52.d.11.G',4,"Which feed is typically higher in protein?","Alfalfa hay",["Straw","Corn stalks","Sawdust"],"Alfalfa is a legume with high protein.")
H('52.d.11.H',3,"Alfalfa and clover are:","Legume forages",["Grains","Minerals","Fertilizers"],"Legumes are high in protein and fix nitrogen.")
H('52.d.11.H',4,"Bermudagrass is commonly used as:","A warm-season forage",["A cold-season only","A mineral","A bedding material only"],"It grows in hot weather and supplies grazing and hay.")
H('52.d.11.I',3,"Rotational grazing means:","Moving animals among pastures to rest the land",["Leaving animals in one place forever","Never grazing","Feeding only grain"],"Rest allows plants to regrow.")
H('52.d.11.I',4,"A benefit of rotational grazing is:","Improved pasture growth and reduced overgrazing",["More weeds always","Less forage","No benefits"],"Pasture health improves with rest periods.")

H('52.d.12.A',3,"Mendel's law of segregation says that:","Alleles separate when gametes form",["Genes never separate","All traits blend","Genes are not inherited"],"Each gamete gets one allele of each pair.")
H('52.d.12.A',4,"If two heterozygous (Aa) animals are crossed, the expected ratio of phenotypes for a dominant trait is:","3 dominant to 1 recessive",["1 to 1","All dominant","All recessive"],"Aa x Aa gives 1 AA, 2 Aa, 1 aa, so 3 show the dominant trait.")
H('52.d.12.B',3,"A Punnett square is used to:","Predict possible offspring genotypes",["Weigh animals","Measure feed","Count cells"],"It maps gamete combinations.")
H('52.d.12.B',4,"Crossing Rr with rr gives offspring that are:","A mix of heterozygous and homozygous recessive",["Every one heterozygous","Every one homozygous recessive","Every one homozygous dominant"],"Half receive R and half receive r from the first parent.")
H('52.d.12.C',3,"A nucleotide contains a sugar, a phosphate, and a:","Nitrogen base",["Protein","Mineral","Fat"],"Bases include A, T, C and G (U in RNA).")
H('52.d.12.C',4,"DNA differs from RNA because DNA has the sugar:","Deoxyribose",["Ribose","Glucose","Fructose"],"RNA has ribose and uracil.")
H('52.d.12.D',3,"The function of DNA is to:","Store the genetic information",["Digest food","Carry oxygen","Produce hair"],"DNA carries instructions for traits.")
H('52.d.12.D',4,"The function of messenger RNA is to:","Carry instructions from DNA to make proteins",["Store DNA","Make bone","Fight disease"],"mRNA copies the code to ribosomes.")

H('52.d.13.A',3,"The female reproductive structure where eggs are produced is the:","Ovary",["Testis","Kidney","Liver"],"The ovary produces eggs and hormones.")
H('52.d.13.A',4,"A major difference between a cow's and a sow's reproductive tract is:","Uterine shape and number of offspring carried",["Their color","Hair type","Hoof size"],"Species differ in uterine type.")
H('52.d.13.B',3,"The period when a female is receptive to mating is called:","Estrus",["Gestation","Lactation","Parturition"],"Estrus is also called heat.")
H('52.d.13.B',4,"The estrous cycle in cattle averages about:","21 days",["3 days","60 days","200 days"],"Cattle cycle about every three weeks.")
H('52.d.13.C',3,"A cow in heat often:","Mounts others and becomes restless",["Sleeps all day","Stops moving","Refuses all contact"],"Behavior changes signal estrus.")
H('52.d.13.C',4,"Why do producers watch behavior to find estrus?","To time breeding for the best chance of pregnancy",["To increase feed costs","To end breeding","To avoid records"],"Timing affects conception.")
H('52.d.13.D',3,"Crossbreeding combines:","Two different breeds",["Two siblings only","Plants and animals","Two identical animals"],"It can improve hybrid vigor.")
H('52.d.13.D',4,"Linebreeding concentrates the genes of:","A particular ancestor",["Unrelated animals","Many breeds","No parents"],"It mates related animals to keep traits.")
H('52.d.13.E',3,"Artificial insemination involves:","Placing semen into a female without natural mating",["Natural mating only","Surgery to remove organs","Removing eggs only"],"AI allows use of superior sires.")
H('52.d.13.E',4,"Embryo transfer allows a producer to:","Get many offspring from a top-quality female",["Prevent pregnancy","Avoid genetics","End breeding"],"Embryos are placed in recipient females.")

H('52.d.14.A',3,"Which factor can affect how likely an animal is to get a disease?","Age and genetic makeup",["Color of the barn","Time of the news","The farmer's hat"],"Host and environment factors influence risk.")
H('52.d.14.A',4,"Crowded housing increases disease risk because it:","Allows pathogens to spread easily",["Lowers stress","Prevents contact","Cleans the air"],"Close contact helps transmission.")
H('52.d.14.B',3,"Colostrum gives newborn calves:","Antibodies for early immunity",["Hay","Water only","Minerals only"],"First milk passes maternal antibodies.")
H('52.d.14.B',4,"Passive immunity is protection that comes from:","Antibodies received from another source",["Making your own antibodies","Vaccination alone","Exercise"],"Passive immunity is borrowed.")
H('52.d.14.C',3,"Brucellosis is caused by a:","Bacterium",["Virus","Parasite","Mineral lack"],"Brucella bacteria cause reproductive disease.")
H('52.d.14.C',4,"Foot-and-mouth disease is caused by a:","Virus",["Bacterium","Fungus","Protozoan"],"It is a highly contagious viral disease.")
H('52.d.14.D',3,"Mastitis affects the:","Udder",["Hoof","Eyes","Liver"],"Mastitis is an infection of the mammary gland.")
H('52.d.14.D',4,"Respiratory disease in feedlot cattle can reduce:","Weight gain and profit",["Feed price","Hay quality","Soil nutrients"],"Sick animals perform poorly.")
H('52.d.14.E',3,"Vaccination programs aim to:","Prevent disease outbreaks",["Cause disease","Remove all animals","Stop feeding"],"Prevention is cheaper than treatment.")
H('52.d.14.E',4,"Quarantining new animals helps by:","Keeping possible disease from the herd",["Spreading disease","Reducing records","Increasing feed"],"Separation allows observation.")
H('52.d.14.F',3,"Lice and mites are:","External parasites",["Internal worms","Bacteria","Minerals"],"They live on the skin or hair.")
H('52.d.14.F',4,"Stomach worms in sheep are:","Internal parasites",["External parasites","Fungi","Viruses"],"They live in the digestive tract.")
H('52.d.14.G',3,"Breaking a parasite's life cycle helps by:","Reducing the number of parasites",["Increasing them","Having no effect","Making it worse"],"Control at key stages lowers infestations.")
H('52.d.14.G',4,"Grazing on pasture with infective larvae increases the risk of:","Internal parasite infection",["Better growth","Fewer worms","Vitamin gain"],"Larvae on grass are swallowed by grazing animals.")
H('52.d.14.H',3,"Parasites can reduce animal performance by:","Taking nutrients and causing damage",["Adding nutrients","Improving growth","Preventing disease"],"Heavy infestations cause poor gain and anemia.")
